PROGRAM p_cnt_2_motor
VAR_INPUT
    Pulse : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    Count : INT;
    PrevPulse : BOOL;
END_VAR
VAR CONSTANT
    CAP : INT := 2;
END_VAR

IF Reset THEN
    Count := 0;
ELSIF Pulse AND NOT PrevPulse AND Count < CAP THEN
    Count := Count + 1;
END_IF;

PrevPulse := Pulse;
Motor := Count >= CAP;

END_PROGRAM

