PROGRAM p_udn_2_bay
VAR_INPUT
    Inc : BOOL;
    Dec : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Bay : BOOL;
END_VAR
VAR
    Count : INT;
    PrevInc : BOOL;
    PrevDec : BOOL;
END_VAR
VAR CONSTANT
    CAP : INT := 2;
END_VAR

IF Reset THEN
    Count := 0;
ELSIF Inc AND NOT PrevInc AND Count < CAP THEN
    Count := Count + 1;
ELSIF Dec AND NOT PrevDec AND Count > 0 THEN
    Count := Count - 1;
END_IF;

PrevInc := Inc;
PrevDec := Dec;
Bay := Count >= CAP;

END_PROGRAM

